/**
 * PRIVATE PDF preview adapter for the owner's final editable Lovely HTML.
 * No HTTP fetch/export, route mount, storage, image upload or customer issue.
 * The caller supplies already-authenticated, tenant-scoped authorization and
 * an isolated browser and PDF engine. Generated bytes are preview-only.
 */
import {renderLovelyFinalQuotationPrintHtml} from "./quotation-final-html-print.mjs";
import {LOVELY_FINAL_HTML_REFERENCE} from "./quotation-final-html-contract.mjs";

const reject=code=>{throw Error(code)};
const A4={width:595.28,height:841.89};
const validId=s=>typeof s==="string"&&/^[a-zA-Z0-9_-]{1,90}$/.test(s);
const within=(a,b)=>Math.abs(a-b)<=1.1;

/**
 * Host MUST enforce the real session/tenant permission and CSRF before
 * invoking this function. This rechecks a trusted independent authority.
 */
export async function renderLovelyFinalQuotationPrivatePdf({
  actor,companyId,draft,authority,browser,pdfLib,sourceSha256
}={}){
 if(sourceSha256!==LOVELY_FINAL_HTML_REFERENCE.sourceSha256)
   reject("lovely_html_source_identity_mismatch");
 if(!validId(companyId)||!actor||typeof authority?.assertPrivatePreview!=="function")
   reject("lovely_html_private_authorization_required");
 const authorized=await authority.assertPrivatePreview({actor,companyId,mode:"synthetic-preview"});
 if(authorized!==true)reject("lovely_html_private_authorization_denied");
 if(typeof browser?.newPage!=="function"||
    typeof pdfLib?.PDFDocument?.load!=="function")
   reject("lovely_html_private_pdf_engine_unavailable");
 const {html}=renderLovelyFinalQuotationPrintHtml(draft);
 let page;
 try{
   page=await browser.newPage({viewport:{width:1100,height:900}});
   await page.setContent(html,{waitUntil:"load"});
   await page.emulateMedia({media:"print"});
   await page.evaluate(()=>document.fonts.ready);
   // A print-break rule never proves text is visible: inspect descendants.
   const geometry=await page.evaluate(()=>[...document.querySelectorAll("article.page")].map(parent=>{
     const rect=parent.getBoundingClientRect();
     const clipped=[...parent.querySelectorAll("*")].some(child=>{
       const b=child.getBoundingClientRect();
       return b.top<rect.top-1||b.bottom>rect.bottom+1||
         b.left<rect.left-1||b.right>rect.right+1||
         child.scrollHeight>child.clientHeight+2||
         child.scrollWidth>child.clientWidth+2;
     });
     return {clipped,scrollHeight:parent.scrollHeight,
       clientHeight:parent.clientHeight};
   }));
   if(!Array.isArray(geometry)||geometry.length!==2||
      geometry.some(p=>p.clipped||p.scrollHeight>p.clientHeight+2))
     reject("lovely_html_print_geometry_overflow");
   const bytes=await page.pdf({format:"A4",preferCSSPageSize:true,printBackground:true});
   if(!(bytes instanceof Uint8Array)||bytes.byteLength===0||
      bytes.byteLength>5*1024*1024)
     reject("lovely_html_print_pdf_invalid_bytes");
   const doc=await pdfLib.PDFDocument.load(bytes);
   if(doc.getPageCount()!==2||doc.getPages().some(p=>{
     const size=p.getSize();
     return !within(size.width,A4.width)||!within(size.height,A4.height);
   }))reject("lovely_html_print_pdf_invalid_page_geometry");
   return Object.freeze({bytes,contentType:"application/pdf",
     pageCount:2,previewOnly:true,sourceSha256});
 }finally{
   if(page)await page.close();
 }
}
